INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (1, 'cruise', '0i5el041vd6nxrGEU8QRxy', 'Here''s To The Good Times', 'https://i.scdn.co/image/ab67616d0000b273f5601676db551cb2a09e70a0', 2012, false, 208960, 75, 1, NULL, 'Florida Georgia Line', 'GROUP', 'Now, let''s dive into the story behind ''Cruise'' by Florida Georgia Line. Did you know that this track was originally written by the duo''s Tyler Hubbard and Brian Kelley in a small cabin in Georgia? They wanted to capture the feeling of freedom and the open road, and boy, did they nail it! ''Cruise'' not only became a breakout hit but also set a record for the longest run at number one on the Country Airplay chart. And here''s a fun fact: the song''s infectious beat was inspired by a mix of hip-hop and country, showcasing the duo''s innovative approach to music. Keep your radio locked right here, because we''ve got more great stories coming up!', '2025-07-26 09:33:16.995758');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (2, 'die a happy man', '5kNe7PE09d6Kvw5pAsx23n', 'Tangled Up', 'https://i.scdn.co/image/ab67616d0000b273f00a1acf866539632b187ea0', 2015, false, 227426, 78, 2, NULL, 'Thomas Rhett', 'SOLO', 'Let''s take a closer look at ''Die a Happy Man'' by Thomas Rhett. This heartfelt ballad was penned by Thomas Rhett himself, along with Sean Douglas and Joe London, and it was inspired by his love for his wife, Lauren. The song''s emotional depth struck a chord with listeners, soaring to the top of the charts and earning Thomas Rhett his first Grammy nomination. Did you know that the recording session was filled with laughter and tears, reflecting the song''s genuine sentiment? And here''s a little trivia for you: the song''s beautiful piano intro was recorded in one take, adding to its raw and authentic feel. Stay tuned, because we''re just getting started on this musical journey!', '2025-07-26 09:33:16.995758');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (3, 'i hope you dance', '65B1tEOv5W294uCKbmEcFV', 'I Hope You Dance', 'https://i.scdn.co/image/ab67616d0000b27363b3168c1970294e9ce5c415', 2000, false, 294533, 66, 3, NULL, 'Lee Ann Womack', 'SOLO', 'Did you know that ''I Hope You Dance'' was co-written by Tia Sillers and Mark D. Sanders in a Nashville coffee shop? The song''s uplifting message resonated so deeply that it not only topped the country charts but also crossed over to pop, reaching number 14 on the Billboard Hot 100. Lee Ann Womack''s heartfelt delivery was recorded in a single take, capturing the raw emotion that has touched millions. And remember, folks, keep dancing through life, because you never know what''s around the corner!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (4, 'where were you when the world stopped turning', '4aOQG9TYcZOhT3sngkMI9K', 'Drive', 'https://i.scdn.co/image/ab67616d0000b273c5d5d983f8d9edc7f695cc72', 2002, false, 305093, 58, 4, NULL, 'Alan Jackson', 'SOLO', 'Alan Jackson penned ''Where Were You When the World Stopped Turning'' in the wake of 9/11, capturing the nation''s grief and resilience. Recorded in a single day at the Sound Station studio in Nashville, the song''s poignant lyrics struck a chord, earning Jackson a standing ovation at the CMA Awards. It''s a testament to the power of music to heal and unite us in times of tragedy. Keep those memories close, and let''s keep moving forward together, my friends.', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (5, 'amazed', '6qc34bnVOyqGDPni8H5W0U', 'Lonely Grill', 'https://i.scdn.co/image/ab67616d0000b27341d35bfbac1ba0af6180206f', 1999, false, 240866, 74, 5, NULL, 'Lonestar', 'GROUP', 'Lonestar''s ''Amazed'' was a labor of love, crafted by songwriters Marv Green, Aimee Mayo, and Chris Lindsey. The band recorded it in a cozy studio in Nashville, where they experimented with lush harmonies and a sweeping orchestral arrangement. The song not only topped the country charts but also became a crossover hit, reaching number one on the Billboard Hot 100. It''s a reminder that love can truly amaze us, so keep those hearts open, folks!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (6, 'courtesy of the red white and blue the angry american', '0M7mWKqwTIaVjYyxfZmtTa', 'Unleashed', 'https://i.scdn.co/image/ab67616d0000b273bb5c54a68f9ce31f83b98de4', 2002, false, 195533, 80, 6, NULL, 'Toby Keith', 'SOLO', 'Toby Keith''s ''Courtesy of the Red, White and Blue (The Angry American)'' was born from raw emotion following 9/11. Keith wrote it in a burst of patriotic fervor, and the song''s bold lyrics stirred both controversy and admiration. Recorded in a Nashville studio, the track''s intensity was captured in a single take. It became an anthem for many, reflecting the nation''s complex feelings. And remember, folks, it''s okay to feel and express those deep emotions.', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (7, 'its five oclock somewhere', '7KysI43rsjlhjTeWO6ePUq', 'Greatest Hits Volume II', 'https://i.scdn.co/image/ab67616d0000b2734dba85eab31b275e997a12d4', 2003, false, 229800, 74, 4, NULL, 'Alan Jackson and Jimmy Buffett', 'DUET', 'Alan Jackson and Jimmy Buffett teamed up for ''It''s Five O''Clock Somewhere,'' a song that became an instant classic. Written by Jim ''Moose'' Brown and Don Rollins, the track was recorded in a relaxed session that captured the laid-back vibe perfectly. It topped the charts and became a summer anthem, reminding us all to take a break and enjoy life. So, next time you''re feeling stressed, remember, it''s always five o''clock somewhere!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (8, 'redneck woman', '26bL4gSULWDgdIMX0pRFrG', 'Here For The Party', 'https://i.scdn.co/image/ab67616d0000b273ddf15202c076358827b81302', 2004, false, 221333, 68, 8, NULL, 'Gretchen Wilson', 'SOLO', 'Gretchen Wilson''s ''Redneck Woman'' was a game-changer, co-written by Wilson and John Rich. Recorded in a Nashville studio, the song''s raw energy and unapologetic lyrics broke the mold, empowering women across the country. It soared to the top of the charts and became an anthem for authenticity. Wilson''s fiery delivery was captured in a single take, adding to the song''s gritty charm. Keep being yourself, folks, because that''s what makes you special!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (9, 'save a horse ride a cowboy', '5s7m2xNZWgz5FqVSIvJcGA', 'Horse of a Different Color', 'https://i.scdn.co/image/ab67616d0000b273805374f00048ac081460cc70', 2004, false, 200306, 75, 9, NULL, 'Big & Rich', 'SOLO', 'Big & Rich''s ''Save a Horse (Ride a Cowboy)'' was a wild ride from the start. Co-written by the duo and John Rich''s brother, the song was recorded in a Nashville studio with a lively, party atmosphere. It became a crossover hit, blending country with rock and even a bit of hip-hop. The song''s infectious energy and playful lyrics made it a favorite at parties everywhere. So, next time you''re out, remember to save a horse and ride a cowboy!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (10, 'suds in the bucket', '6NhpIdjYoufuNNlBsgOztc', 'Restless', 'https://i.scdn.co/image/ab67616d0000b2739b6f689d6687f8930c154a86', 2003, false, 227266, 70, 10, NULL, 'Sara Evans', 'SOLO', 'Sara Evans'' ''Suds in the Bucket'' was penned by Billy Montana and Tammy Wagoner, capturing the spirit of youthful rebellion. Recorded in a Nashville studio, the song''s catchy melody and relatable lyrics struck a chord with listeners. It topped the country charts and became a summer anthem, reminding us of those carefree days. Evans'' sweet vocals and the song''s playful vibe make it a timeless classic. So, keep chasing those dreams, folks, no matter what anyone says!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (11, 'when the sun goes down', '5vLonpxn4VN0A8GtQOBSG0', 'When The Sun Goes Down', 'https://i.scdn.co/image/ab67616d0000b273528e4965b251e5f09dd32761', 2004, false, 290560, 72, 11, NULL, 'Kenny Chesney and Uncle Kracker', 'DUET', 'Kenny Chesney and Uncle Kracker teamed up for ''When the Sun Goes Down,'' a song that captured the essence of a perfect summer night. Written by Chesney and Brett James, the track was recorded in a relaxed session that mirrored its laid-back vibe. It topped the charts and became a staple at beach parties everywhere. The song''s infectious melody and feel-good lyrics remind us to enjoy the simple moments in life. So, next time the sun goes down, take a moment to savor it!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (12, 'live like you were dying', '7B1QliUMZv7gSTUGAfMRRD', 'Live Like You Were Dying', 'https://i.scdn.co/image/ab67616d0000b273e6b859b16a880b851822871d', 2004, false, 300333, 71, 13, NULL, 'Tim McGraw', 'SOLO', 'Tim McGraw''s ''Live Like You Were Dying'' was inspired by a friend''s battle with illness, co-written by McGraw and Craig Wiseman. Recorded in a Nashville studio, the song''s powerful message and McGraw''s emotional delivery struck a chord with listeners. It topped the charts and won multiple awards, becoming an anthem for living life to the fullest. The song''s impact reminds us to cherish every moment. So, keep living like you were dying, my friends, because every day is a gift!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (13, 'im already there', '34Vn9nKfztyLco9lJazy4j', 'I''m Already There', 'https://i.scdn.co/image/ab67616d0000b27315ea142bd41376087c24d6fe', 2001, false, 253373, 60, 5, NULL, 'Lonestar', 'GROUP', 'Did you know that ''I''m Already There'' was inspired by a real-life story of a band member missing his family while on tour? The songwriters, Gary Baker and Richie McDonald, crafted this heartfelt tune in a cozy Nashville studio, surrounded by family photos for inspiration. It soared to the top of the charts, becoming a beacon of hope for families separated by distance. And here''s a fun fact: the band recorded it with a live string section to capture that emotional swell. So, keep your loved ones close, and remember, you''re never as far away as you think. And that''s your long-distance dedication from me to you!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (14, 'beer for my horses', '7E2DqvnVtbIrFrL5X6YH9Q', 'Unleashed', 'https://i.scdn.co/image/ab67616d0000b273bb5c54a68f9ce31f83b98de4', 2002, false, 204000, 75, 6, NULL, 'Toby Keith and Willie Nelson', 'DUET', 'Toby Keith teamed up with the legendary Willie Nelson to bring us ''Beer for My Horses'', a song that''s as fun as it is controversial. Did you know they filmed the music video in downtown Nashville, turning the streets into a wild west scene? The songwriters, Toby Keith and Scotty Emerick, drew inspiration from old western films, aiming to capture that rugged spirit. It climbed the charts, sparking debates and discussions across the country. And here''s a little trivia: Toby and Willie had a blast on set, even sharing a few cold ones. So, saddle up and enjoy the ride, because that''s the spirit of country music. Keep it tuned right here!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (15, 'mayberry', '04rZkq3ihHmGNfKPgBiTX1', 'Melt', 'https://i.scdn.co/image/ab67616d0000b2736f14b3d807c3aed1d73a7d6b', 2002, false, 272986, 58, 15, NULL, 'Rascal Flatts', 'GROUP', 'Rascal Flatts took us back to simpler times with ''Mayberry'', a song that resonates with anyone longing for the good old days. The songwriters, Arlos Smith and Rodney Clawson, crafted this nostalgic gem in a small, rustic studio, aiming to capture the essence of small-town America. It quickly became a fan favorite, climbing the charts and touching hearts. Fun fact: the band used real-life stories from their own childhoods to add authenticity. So, take a moment to appreciate the simple joys in life, and remember, sometimes the best things are right in your own backyard. And that''s your trip down memory lane, courtesy of Rascal Flatts!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (16, 'bless the broken road', '4YjjNHtEsTX6Af4mCTupT5', 'Feels Like Today', 'https://i.scdn.co/image/ab67616d0000b273d1ca2ddde8ff17e3991de83d', 2004, false, 226680, 74, 15, NULL, 'Rascal Flatts', 'GROUP', 'Rascal Flatts'' ''Bless the Broken Road'' is a testament to the journey of life and love. Did you know this song was originally recorded by the Nitty Gritty Dirt Band? The songwriters, Marcus Hummon, Bobby Boyd, and Jeff Hanna, poured their hearts into the lyrics, reflecting on life''s twists and turns. Rascal Flatts'' version soared to the top of the charts, becoming a wedding staple. And here''s a fun fact: the band recorded it in a single take, capturing the raw emotion. So, embrace every step of your journey, because it leads you to where you''re meant to be. And that''s your heartfelt dedication from Rascal Flatts!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (17, 'days go by', '2jwaErbghhcia4JqUYWz3g', 'Be Here', 'https://i.scdn.co/image/ab67616d0000b273930122975ef092c853ed28ac', 2002, false, 224629, 65, 16, NULL, 'Keith Urban', 'SOLO', 'Keith Urban''s ''Days Go By'' is a vibrant celebration of life''s fleeting moments. Did you know that Keith wrote this song in a burst of inspiration while on a road trip? The song captures the essence of living in the moment, and it was recorded in a lively studio session with a full band. It quickly climbed the charts, resonating with fans who appreciate the joy of the present. And here''s a fun fact: Keith played multiple instruments on the track, showcasing his versatility. So, take a moment to enjoy the day, because as Keith reminds us, they go by all too fast. Keep it locked right here for more great tunes!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (18, 'somebody like you', '0b9djfiuDIMw1zKH6gV74g', 'Golden Road', 'https://i.scdn.co/image/ab67616d0000b2736b884d4969e2438f5a83ed5b', 2002, false, 323040, 74, 16, NULL, 'Keith Urban', 'SOLO', 'Keith Urban''s ''Somebody Like You'' is a love song that captured hearts worldwide. Did you know that Keith wrote this song with John Shanks, and they recorded it in a marathon session, fueled by coffee and passion? The song soared to the top of the charts, becoming a crossover hit. And here''s a fun fact: Keith played the banjo on the track, adding a unique flavor. So, if you''re searching for that special someone, remember, they might be closer than you think. And that''s your love song dedication from Keith Urban, right here on the radio!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (19, 'youll think of me', '68Iw932AjRCDEPLIzpmOtF', 'Golden Road', 'https://i.scdn.co/image/ab67616d0000b2736b884d4969e2438f5a83ed5b', 2004, false, 293600, 62, 16, NULL, 'Keith Urban', 'SOLO', 'Keith Urban''s ''You''ll Think of Me'' is a poignant reflection on moving on. Did you know that Keith wrote this song after a personal breakup, pouring his emotions into every lyric? The song was recorded in a quiet studio, allowing the raw emotion to shine through. It climbed the charts, resonating with anyone who''s ever had to say goodbye. And here''s a fun fact: Keith played the guitar solo in one take, capturing the song''s intensity. So, if you''re going through a tough time, remember, it''s okay to let go and move forward. And that''s your heartfelt message from Keith Urban, right here on the airwaves!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (20, 'im movin on', '7gpuC3rLKkI7PoJcEnSIO6', 'Rascal Flatts', 'https://i.scdn.co/image/ab67616d0000b273f7cfbbae7af7a43957580b00', 2000, false, 242866, 51, 15, NULL, 'Rascal Flatts', 'GROUP', 'Rascal Flatts'' ''I''m Movin'' On'' is an anthem of resilience and hope. Did you know that the songwriters, D. Vincent Williams and Phillip White, drew inspiration from their own life experiences? The band recorded it in a Nashville studio, capturing the song''s uplifting spirit. It quickly became a fan favorite, climbing the charts and inspiring listeners. And here''s a fun fact: the band performed it live at the Grand Ole Opry, receiving a standing ovation. So, if you''re facing challenges, remember, you have the strength to move on. And that''s your uplifting message from Rascal Flatts, right here on the radio!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (21, 'these days', '5nWgEBtaRwVrCMjer1RtLm', 'Melt', 'https://i.scdn.co/image/ab67616d0000b2736f14b3d807c3aed1d73a7d6b', 2002, false, 254493, 61, 15, NULL, 'Rascal Flatts', 'GROUP', 'Rascal Flatts'' ''These Days'' is a song that captures the essence of modern life. Did you know that the songwriters, Steve Robson, Jeffrey Steele, and Danny Wells, crafted this tune in a bustling Nashville studio? The song reflects on the fast pace of today''s world, resonating with listeners everywhere. It climbed the charts, becoming a staple on country radio. And here''s a fun fact: the band used a mix of traditional and modern instruments to create its unique sound. So, take a moment to appreciate the beauty of these days, because they''re all we''ve got. And that''s your modern-day dedication from Rascal Flatts!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (22, 'fast cars and freedom', '0CKba2KBPP9TFbh5Nf8i4P', 'Feels Like Today', 'https://i.scdn.co/image/ab67616d0000b273d1ca2ddde8ff17e3991de83d', 2004, false, 262186, 66, 15, NULL, 'Rascal Flatts', 'GROUP', 'Rascal Flatts'' ''Fast Cars and Freedom'' is a song that celebrates the joys of youth and freedom. Did you know that the songwriters, Gary Levox, Wendell Mobley, and Neil Thrasher, drew inspiration from their own teenage memories? The band recorded it in a lively studio session, capturing the song''s energetic spirit. It quickly became a fan favorite, climbing the charts and becoming a summer anthem. And here''s a fun fact: the band used real car sounds in the recording to add authenticity. So, if you''re feeling nostalgic, crank up the volume and let the memories take you back. And that''s your summer soundtrack from Rascal Flatts, right here on the radio!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (23, 'what hurts the most', '4bVuIlGQBMWS7vIhcx8Ae4', 'Me And My Gang', 'https://i.scdn.co/image/ab67616d0000b273aa6b03f85a0f2cb16e88ec0c', 2006, false, 214106, 74, 15, NULL, 'Rascal Flatts', 'GROUP', 'Now, let''s dive into the heart of ''What Hurts the Most'' by Rascal Flatts. This gem was penned by Jeffrey Steele and Steve Robson, originally for Mark Wills, but it found its true home with Rascal Flatts. Did you know that during the recording, the band aimed for a raw, emotional sound, which you can hear in those haunting vocals? The song climbed to the top of the charts, staying at number one on the Billboard Hot Country Songs for four weeks. It''s a testament to the power of heartfelt songwriting. And remember, folks, keep those emotions close, because that''s where the magic happens. Keep it locked right here!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (24, 'my wish', '6Gfmj0HbpvxTdW0sdlzTDU', 'Me And My Gang', 'https://i.scdn.co/image/ab67616d0000b273aa6b03f85a0f2cb16e88ec0c', 2006, false, 248280, 68, 15, NULL, 'Rascal Flatts', 'GROUP', 'Let''s take a moment to appreciate ''My Wish'' by Rascal Flatts. This touching ballad was co-written by the legendary duo of Jeffrey Steele and Steve Robson, the same masterminds behind ''What Hurts the Most''. The song was inspired by Steele''s own daughter, adding a personal touch that resonates with listeners. Recorded in the cozy confines of Ocean Way Nashville, the track features lush strings that elevate its emotional impact. It soared to number one on the country charts, a true testament to its universal appeal. And as always, keep your wishes close, and your radio closer. Stay tuned!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (25, 'stand', '3tDo6YZzIZlc5gRy31lvJD', 'Life Is A Highway: Refueled Duets', 'https://i.scdn.co/image/ab67616d0000b2735a42bd25f34b900afa225eeb', 2007, false, 210600, 63, 15, NULL, 'Rascal Flatts', 'GROUP', 'Now, let''s stand up for ''Stand'' by Rascal Flatts. This uplifting anthem was crafted by the talented duo of Blair Daly and Danny Orton. The song was recorded at the iconic Starstruck Studios, where the band aimed to capture a sense of unity and strength. Did you know that ''Stand'' was inspired by the resilience of everyday heroes? It''s a powerful reminder of the impact one person can have. The track reached the top of the charts, staying at number one for two weeks. So, stand tall and proud, and keep your dial right here for more great music!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (26, 'life is a highway', '2Fs18NaCDuluPG1DHGw1XG', 'Me And My Gang', 'https://i.scdn.co/image/ab67616d0000b273aa6b03f85a0f2cb16e88ec0c', 2006, false, 276320, 77, 15, NULL, 'Rascal Flatts', 'GROUP', 'Let''s hit the road with ''Life Is a Highway'' by Rascal Flatts. This energetic cover was originally penned by Tom Cochrane, but Rascal Flatts brought their own flair to it. Recorded at the legendary Sound Kitchen in Nashville, the band added a country twist that made it a hit. Did you know that the song was featured in the movie ''Cars'', boosting its popularity? It raced to the top of the charts, staying at number one for four weeks. So, buckle up and enjoy the ride, and keep your radio tuned right here!', '2025-07-24 14:17:46.910223');
