INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (43, 'remind me', '4ABua0yuWcpTotImEEJTaw', 'This Is Country Music', 'https://i.scdn.co/image/ab67616d0000b273e4ed191be04ba0e4253c77f4', 2011, false, 271906, 61, 18, NULL, 'Brad Paisley and Carrie Underwood', 'DUET', 'Now, let''s dive into the heart of ''Remind Me''. This gem was co-written by Brad Paisley and Chris DuBois, and it''s a testament to the power of nostalgia in music. Recorded at The Castle Recording Studios, the song features a unique blend of Paisley''s signature guitar work and the soulful vocals of Carrie Underwood. Did you know that the song''s video was shot in black and white to emphasize the timeless feel of the lyrics? It''s a beautiful reminder that some memories are worth revisiting. And that, my friends, is the magic of music, keeping us connected to the moments that matter. Keep those memories alive, and keep your radio tuned right here!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (44, 'im gonna miss her the fishin song', '4ipZsAA3YuqCDSXiPoEGIv', 'Part II', 'https://i.scdn.co/image/ab67616d0000b27394da46e08a9a9971436da68a', 2001, false, 194306, 68, 18, NULL, 'Brad Paisley', 'SOLO', 'Alright, let''s cast our lines into the story of ''I''m Gonna Miss Her (The Fishin'' Song)''. This track was born from a playful conversation between Brad Paisley and his co-writer, Kelley Lovelace, about the age-old dilemma of love versus fishing. The song was recorded at The Castle Recording Studios, where Paisley''s guitar twang perfectly captures the light-hearted spirit of the lyrics. Fun fact: the music video features Brad actually fishing, adding a touch of authenticity to the song''s theme. It''s a humorous take on priorities, and it''s climbed the charts with the ease of a well-cast lure. So, keep your rods ready and your radio on, because you never know when the next big catch will come along!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (45, 'celebrity', '1Jmkm1iiVn6cxiKRaOlqOW', 'Mud On The Tires', 'https://i.scdn.co/image/ab67616d0000b2737302ccf08d789304c55ee73e', 2003, false, 223200, 47, 18, NULL, 'Brad Paisley', 'SOLO', 'Let''s roll out the red carpet for ''Celebrity''. This track was crafted by Brad Paisley alongside co-writers Chris DuBois and Kelley Lovelace, and it''s a satirical look at fame. Recorded at The Castle Recording Studios, the song features a catchy beat that''s as infectious as the fame it critiques. Did you know that the music video parodies various celebrities, adding a visual punch to the song''s message? It''s a clever commentary on the allure and absurdity of stardom. So, keep your eyes on the stars, but keep your feet on the ground, and stay tuned right here for more hits!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (46, 'little moments', '1hrCqasBFvB9IyLhrABVhc', 'Mud On The Tires', 'https://i.scdn.co/image/ab67616d0000b2737302ccf08d789304c55ee73e', 2003, false, 219266, 54, 18, NULL, 'Brad Paisley', 'SOLO', 'Let''s take a moment to appreciate ''Little Moments''. This heartfelt track was penned by Brad Paisley and Chris DuBois, and it''s all about cherishing the small things in life. Recorded at The Castle Recording Studios, the song''s gentle melody and Paisley''s warm vocals create an intimate atmosphere. Fun fact: the song''s video was filmed in a cozy home setting, emphasizing the personal nature of the lyrics. It''s a reminder that sometimes, the little moments are the ones that mean the most. So, keep your heart open to those little joys, and keep your radio locked right here!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (47, 'me neither', '6A426nfNHDuTDs1uY0W0NF', 'Who Needs Pictures', 'https://i.scdn.co/image/ab67616d0000b273f8be6a6e73ff1219404c7a27', 1999, false, 200160, 44, 18, NULL, 'Brad Paisley', 'SOLO', 'Let''s tip our hats to ''Me Neither''. This witty track was co-written by Brad Paisley and Chris DuBois, and it''s a playful take on shared dislikes. Recorded at The Castle Recording Studios, the song''s clever lyrics and Paisley''s smooth delivery make it a fun listen. Did you know that the song''s video features Brad in various humorous situations, perfectly matching the song''s light-hearted vibe? It''s a reminder that sometimes, finding common ground can be as simple as agreeing on what you don''t like. So, keep your sense of humor handy, and keep your radio tuned right here for more great tunes!', '2025-07-24 14:17:46.910223');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (48, 'crazy in love', '5IVuqXILoxVWvWEPm82Jxr', 'Dangerously In Love', 'https://i.scdn.co/image/ab67616d0000b27345680a4a57c97894490a01c1', 2003, false, 236133, 82, 21, NULL, 'Beyoncé feat. Jay-Z', 'FEATURED', 'Now, let''s dive into the magic behind ''Crazy in Love''. Did you know that the iconic horn riff was sampled from The Chi-Lites'' ''Are You My Woman (Tell Me So)''? It was a last-minute addition that transformed the track into an instant classic. The song was co-written by Beyoncé, her future husband Jay-Z, and producer Rich Harrison. They recorded it in just two hours, capturing the raw energy that you can still feel today. And that, my friends, is the power of spontaneity in music. Keep it locked right here for more behind-the-scenes stories!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (49, 'since u been gone', '3xrn9i8zhNZsTtcoWgQEAd', 'Breakaway', 'https://i.scdn.co/image/ab67616d0000b27303dadde4d9d305c1c3e0d91c', 2004, false, 188960, 79, 23, NULL, 'Kelly Clarkson', 'SOLO', 'Here''s a fun fact about ''Since U Been Gone'': it was originally offered to Pink, but she passed on it. Can you imagine? Kelly Clarkson''s powerhouse vocals made it a smash hit, reaching the top of the charts in multiple countries. The song was penned by Max Martin and Dr. Luke, who crafted its infectious melody in a Swedish studio. Kelly recorded her vocals in just one take, showcasing her incredible talent and emotion. And that, my friends, is how a song can find its perfect voice. Stay tuned for more musical gems!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (50, 'hey ya', '2PpruBYCo4H7WOBJ7Q2EwM', 'Speakerboxxx/The Love Below', 'https://i.scdn.co/image/ab67616d0000b2736e88eb6508fd94cd1b745ce2', 2003, false, 235213, 86, 24, NULL, 'OutKast', 'SOLO', 'Let''s talk about ''Hey Ya!'' by OutKast. This track was a solo effort by André 3000, who wrote and produced it in his bedroom studio. Did you know that the song''s iconic ''shake it like a Polaroid picture'' line was inspired by an actual Polaroid ad? The recording process was unique too, with André playing all the instruments himself. It became a cultural phenomenon, even inspiring a dance craze. And that, my friends, is how one man''s vision can change the music world. Keep it right here for more fascinating stories!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (52, 'yeah', '5rb9QrpfcKFHM1EUbSIurX', 'Confessions (Expanded Edition)', 'https://i.scdn.co/image/ab67616d0000b273365b3fb800c19f7ff72602da', 2004, false, 250373, 88, 27, NULL, 'Usher feat. Lil Jon & Ludacris', 'FEATURED', 'Let''s dive into the story of ''Yeah!'' by Usher. This track was a collaboration with Lil Jon and Ludacris, and it was recorded in just one day. The song''s infectious beat was crafted by Lil Jon, who used a sample from an old-school funk track. Did you know that ''Yeah!'' was originally intended for Petey Pablo? But Usher''s smooth vocals made it a global sensation. And that, my friends, is how a last-minute decision can lead to a mega-hit. Keep it locked right here for more musical tales!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (53, 'i gotta feeling', '2H1047e0oMSj10dgp7p2VG', 'THE E.N.D. (THE ENERGY NEVER DIES)', 'https://i.scdn.co/image/ab67616d0000b273382514f0114ba8f4a16d5db4', 2009, false, 289133, 81, 29, NULL, 'Black Eyed Peas', 'SOLO', 'Let''s explore the magic behind ''I Gotta Feeling'' by the Black Eyed Peas. This anthem was co-written by the group''s own will.i.am, who drew inspiration from a night out in Las Vegas. The song''s uplifting message was exactly what the world needed at the time. Did you know that it was recorded in multiple studios across the globe? The track''s infectious beat and catchy lyrics made it a party staple. And that, my friends, is how a song can capture the spirit of celebration. Stay tuned for more musical journeys!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (54, 'single ladies put a ring on it', '2ZBNclC5wm4GtiWaeh0DMx', 'I AM...SASHA FIERCE', 'https://i.scdn.co/image/ab67616d0000b273e13de7b8662b085b0885ffef', 2008, false, 193213, 68, 21, NULL, 'Beyoncé', 'SOLO', 'Let''s uncover the story behind ''Single Ladies (Put a Ring on It)''. This empowering anthem was co-written by Beyoncé, The-Dream, and Tricky Stewart. The song''s iconic choreography was inspired by Bob Fosse''s ''Mexican Breakfast''. Did you know that the video was shot in just two days, with Beyoncé performing the dance routine over 60 times? The track''s success was a testament to her dedication and vision. And that, my friends, is how a song can become a cultural phenomenon. Keep it locked right here for more behind-the-scenes stories!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (55, 'poker face', '5R8dQOPq8haW94K7mgERlO', 'The Fame', 'https://i.scdn.co/image/ab67616d0000b273613aaa3ae566d9f36008aed0', 2008, false, 237200, 82, 30, NULL, 'Lady Gaga', 'SOLO', 'Let''s delve into the story of ''Poker Face'' by Lady Gaga. This track was inspired by her experiences in the underground club scene. Did you know that the song''s catchy hook was originally about a different topic? Gaga changed it to make it more radio-friendly. The song was co-written with RedOne, who also produced it. They recorded it in a small studio in Los Angeles, capturing the raw energy that made it a global hit. And that, my friends, is how a song can evolve into a worldwide sensation. Stay tuned for more musical tales!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (56, 'umbrella', '2yPoXCs7BSIUrucMdK5PzV', 'Good Girl Gone Bad', 'https://i.scdn.co/image/ab67616d0000b273b9ff0a5f40d3406aed5e5e3b', 2007, false, 275986, 77, 31, NULL, 'Rihanna feat. Jay-Z', 'FEATURED', 'Let''s uncover the magic behind ''Umbrella'' by Rihanna. This track was co-written by The-Dream and Tricky Stewart, who crafted its infectious beat in just a few hours. Did you know that the song was originally intended for Britney Spears? But Rihanna''s powerful vocals made it a global sensation. The track''s success was a testament to her unique style and the song''s universal message. And that, my friends, is how a song can find its perfect voice. Keep it locked right here for more musical gems!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (57, 'hollaback girl', '0LzrhCZFXW94Y8nwtTuRlw', 'Love. Angel. Music. Baby. (Deluxe Version)', 'https://i.scdn.co/image/ab67616d0000b2737c7136a182372ccdffb3d3c4', 2004, false, 199853, 75, 32, NULL, 'Gwen Stefani', 'SOLO', 'Let''s dive into the story of ''Hollaback Girl'' by Gwen Stefani. This track was co-written with Pharrell Williams, who produced it and added his signature sound. Did you know that the song''s iconic cheerleader chant was inspired by Gwen''s high school days? The track was recorded in Pharrell''s home studio, capturing the playful energy that made it a hit. It became the first digital download to sell over a million copies. And that, my friends, is how a song can become a cultural phenomenon. Stay tuned for more musical journeys!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (58, 'toxic', '6I9VzXrHxO9rA9A5euc8Ak', 'In The Zone', 'https://i.scdn.co/image/ab67616d0000b273efc6988972cb04105f002cd4', 2003, false, 198800, 87, 33, NULL, 'Britney Spears', 'SOLO', 'Did you know that ''Toxic'' was originally offered to Kylie Minogue? That''s right, folks! But it was Britney Spears who took this electrifying track to new heights, soaring to the top of the charts in over 20 countries. The song''s infectious beat was crafted by Bloodshy & Avant, who drew inspiration from the sounds of French filter house music. And get this - the iconic video, featuring Britney in a daring array of costumes, was shot in just two days! Keep your radio locked right here, because we''ve got more amazing stories coming up!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (59, 'irreplaceable', '1G7DcLzPnopdZjLkev0K4e', 'B''Day', 'https://i.scdn.co/image/ab67616d0000b273632e4eafb2ffba59a2ae4500', 2006, false, 227666, 73, 21, NULL, 'Beyoncé', 'SOLO', 'Here''s a fun fact about ''Irreplaceable'' - it was written in just two hours by Ne-Yo, originally intended for himself but handed over to the powerhouse that is Beyoncé. This track not only topped the Billboard Hot 100 for 10 weeks but also became an anthem for empowerment. The song''s minimalist production, featuring just an acoustic guitar and a drum machine, showcases Beyoncé''s vocal prowess. And guess what? It was recorded in her home studio! Stay tuned, because we''re spinning more hits and sharing more stories, right here on your favorite station!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (60, 'low', '0CAfXk7DXMnon4gLudAp7J', 'Mail on Sunday', 'https://i.scdn.co/image/ab67616d0000b273f9bd7a6c772ac496015be3f8', 2007, false, 231400, 87, 34, NULL, 'Flo Rida feat. T-Pain', 'FEATURED', 'Let me tell you something fascinating about ''Low'' - it was the first song to sell over 3 million digital copies in the US! Flo Rida''s collaboration with T-Pain was recorded in just one take, showcasing their incredible chemistry. The song''s catchy hook was inspired by a conversation Flo Rida had with a friend about dancing at a club. And here''s a fun tidbit - the ''apple bottom jeans'' mentioned in the lyrics are a real brand! Keep it locked right here for more chart-topping hits and behind-the-scenes stories!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (61, 'bleeding love', '7wZUrN8oemZfsEd1CGkbXE', 'Spirit', 'https://i.scdn.co/image/ab67616d0000b27334fd9eb8cd48e518598aec55', 2007, false, 262466, 79, 36, NULL, 'Leona Lewis', 'SOLO', 'You won''t believe this, but ''Bleeding Love'' was co-written by none other than OneRepublic''s Ryan Tedder! Leona Lewis''s powerhouse vocals took this song to the top of the charts in 35 countries. The song''s emotional depth was inspired by Tedder''s own experiences with heartbreak. And get this - the iconic music video was filmed in a single day in Los Angeles! Stick around, because we''ve got more incredible stories and hits coming your way!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (62, 'boom boom pow', '3opVsyWVYEAFK9bJAG8Opa', 'THE E.N.D. (THE ENERGY NEVER DIES)', 'https://i.scdn.co/image/ab67616d0000b273382514f0114ba8f4a16d5db4', 2009, false, 251440, 72, 29, NULL, 'Black Eyed Peas', 'SOLO', 'Here''s a cool fact about ''Boom Boom Pow'' - it was the first song to top the Billboard Hot 100 chart based solely on digital downloads! The Black Eyed Peas'' futuristic sound was crafted in their home studio, with will.i.am handling much of the production. The song''s title was inspired by a comic book sound effect, adding to its unique vibe. And guess what? It was recorded in just three days! Keep your dial right here for more chart-topping stories and hits!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (63, 'candy shop', '5D2mYZuzcgjpchVY1pmTPh', 'The Massacre', 'https://i.scdn.co/image/ab67616d0000b27391f7222996c531b981e7bb3d', 2005, false, 209106, 83, 37, NULL, '50 Cent feat. Olivia', 'FEATURED', 'Did you know that ''Candy Shop'' was produced by the legendary Scott Storch? That''s right, folks! 50 Cent''s collaboration with Olivia was recorded in Storch''s Miami studio, where the iconic beat was crafted in just one session. The song''s catchy hook was inspired by a conversation 50 Cent had about indulgence. And here''s a fun fact - the ''candy shop'' mentioned in the lyrics is a metaphor for a club! Stay tuned, because we''ve got more amazing stories and hits coming up!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (64, 'just dance', '2x7MyWybabEz6Y6wvHuwGE', 'The Fame', 'https://i.scdn.co/image/ab67616d0000b273613aaa3ae566d9f36008aed0', 2008, false, 241933, 81, 30, NULL, 'Lady Gaga feat. Colby O''Donis', 'FEATURED', 'Here''s something fascinating about ''Just Dance'' - it was Lady Gaga''s debut single, and it skyrocketed to the top of the charts in multiple countries! The song was co-written by Gaga and RedOne, who also produced the track. The infectious beat was inspired by a night out dancing, capturing the essence of letting loose. And get this - the iconic music video was filmed in just one day in Los Angeles! Keep your radio locked right here for more incredible stories and hits!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (65, 'lollipop', '1pm7lQGl6mvKWDxesZTVFp', 'Tha Carter III (MTV Bonus Version)', 'https://i.scdn.co/image/ab67616d0000b27302a999c3a283b5392e57737d', 2008, false, 299333, 74, 40, NULL, 'Lil Wayne feat. Static Major', 'FEATURED', 'You won''t believe this, but ''Lollipop'' was recorded in just one take! Lil Wayne''s collaboration with Static Major was an instant hit, topping the Billboard Hot 100 chart. The song''s catchy hook was inspired by a conversation Wayne had about candy. And here''s a fun fact - the ''lollipop'' mentioned in the lyrics is a metaphor for something sweet! Stick around, because we''ve got more chart-topping stories and hits coming your way!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (66, 'disturbia', '2VOomzT6VavJOGBeySqaMc', 'Good Girl Gone Bad: Reloaded', 'https://i.scdn.co/image/ab67616d0000b273f9f27162ab1ed45b8d7a7e98', 2008, false, 238626, 82, 31, NULL, 'Rihanna', 'SOLO', 'Did you know that ''Disturbia'' was co-written by Chris Brown? That''s right, folks! Rihanna''s haunting track was inspired by a feeling of unease, capturing the essence of being in a disturbed state of mind. The song''s eerie beat was crafted by the production team Stargate, who also worked on many of Rihanna''s other hits. And get this - the iconic music video was filmed in just two days! Keep your dial right here for more incredible stories and hits!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (67, 'hot in herre', '04KTF78FFg8sOHC1BADqbY', 'Nellyville', 'https://i.scdn.co/image/ab67616d0000b273a8b9f97b9ea065b9a857e93f', 2002, false, 228240, 81, 42, NULL, 'Nelly', 'SOLO', 'Here''s a fun fact about ''Hot in Herre'' - it was produced by The Neptunes, and the iconic beat was crafted in just one session! Nelly''s track was inspired by a conversation he had about the heat in a club. The song''s catchy hook became an instant hit, topping the Billboard Hot 100 chart. And guess what? It was recorded in Nelly''s home studio! Stay tuned, because we''ve got more amazing stories and hits coming up!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (68, 'baby boy', '4WY3HyGXsWqjFRCVD6gnTe', 'Dangerously In Love', 'https://i.scdn.co/image/ab67616d0000b27345680a4a57c97894490a01c1', 2003, false, 244826, 72, 21, NULL, 'Beyoncé feat. Sean Paul', 'FEATURED', 'Did you know that ''Baby Boy'' was a collaboration that brought together the sultry sounds of Beyonce with the reggae vibes of Sean Paul? Recorded in Miami, this track was a labor of love, blending genres in a way that only a genius like producer Scott Storch could pull off. The song''s infectious beat was crafted using a sample from the classic reggae tune ''Here Comes the Hotstepper'' by Ini Kamoze. And here''s a fun fact for you: during the recording sessions, Beyonce and Sean Paul had such a blast that they ended up improvising some of the lyrics on the spot! And that''s the magic of music, folks, where spontaneity can lead to chart-topping hits. Keep it locked right here for more behind-the-scenes stories!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (69, 'in da club', '4RY96Asd9IefaL3X4LOLZ8', 'Get Rich Or Die Tryin''', 'https://i.scdn.co/image/ab67616d0000b273f7f74100d5cc850e01172cbf', 2003, false, 193466, 77, 37, NULL, '50 Cent', 'SOLO', 'Let''s dive into the story behind ''In Da Club''. This track was the brainchild of Dr. Dre, who not only produced it but also helped 50 Cent craft those unforgettable lyrics. Recorded in the legendary Record One studio in Sherman Oaks, California, the song''s iconic beat was inspired by a sample from ''It''s Like That'' by Run-DMC. Here''s a little trivia for you: 50 Cent recorded his vocals in just one take, showcasing his raw talent and energy. And did you know that the song''s success was so massive that it became a staple at every party and club across the nation? That''s the power of a hit, my friends, and we''ll be right back with more of those stories you love!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (70, 'firework', '4r6eNCsrZnQWJzzvFh4nlg', 'Teenage Dream', 'https://i.scdn.co/image/ab67616d0000b273d20c38f295039520d688a888', 2010, false, 227893, 77, 44, NULL, 'Katy Perry', 'SOLO', 'Let''s take a closer look at ''Firework'' by Katy Perry. This uplifting anthem was co-written by Perry along with the talented duo of Mikkel S. Eriksen and Tor Erik Hermansen, better known as Stargate. The song''s inspiring lyrics were born out of a desire to empower listeners, with Perry drawing from her own experiences of feeling like an outsider. Recorded in Los Angeles, the track features a soaring chorus that was crafted to make you feel like you can conquer the world. And here''s a fun fact: the song''s music video, directed by Dave Meyers, was inspired by the artwork of artist Dale Chihuly. So, keep your radio tuned right here for more stories that light up your day!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (71, 'tik tok', '5PSba04SiAEUe3q6PyaTpQ', 'TiK-Tok - Remixes', 'https://i.scdn.co/image/ab67616d0000b273233906d0f076db62a4f819d0', 2009, false, 200186, 58, 45, NULL, 'Kesha', 'SOLO', 'Let''s explore the story behind ''Tik Tok'' by Kesha. This infectious track was penned by Kesha herself, along with the prolific songwriter Dr. Luke. The song''s catchy beat was inspired by a sample from ''Don''t Cha'' by The Pussycat Dolls, giving it that irresistible dance vibe. Recorded in Los Angeles, ''Tik Tok'' became an instant party anthem, with Kesha''s playful lyrics and energetic delivery capturing the hearts of listeners everywhere. And here''s a fun fact: Kesha recorded her vocals while brushing her teeth, adding to the song''s quirky charm. So, keep it locked right here for more fun and fascinating stories from the world of music!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (72, 'bad romance', '0SiywuOBRcynK0uKGWdCnn', 'The Fame Monster (Deluxe Edition)', 'https://i.scdn.co/image/ab67616d0000b2735c9890c0456a3719eeecd8aa', 2009, false, 294573, 88, 30, NULL, 'Lady Gaga', 'SOLO', 'Let''s delve into the story behind ''Bad Romance'' by Lady Gaga. This iconic track was co-written by Gaga and the talented RedOne, who also produced the song. Recorded in Los Angeles, ''Bad Romance'' features a blend of electronic and pop elements that create its unique sound. The song''s dramatic lyrics were inspired by Gaga''s own experiences with love and relationships, adding a personal touch to the track. And here''s a fun fact: the song''s music video, directed by Francis Lawrence, became a cultural phenomenon, with its memorable scenes and choreography. So, keep your radio tuned right here for more stories that are as captivating as the music itself!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (73, 'dynamite', '1DqdF42leyFIzqNDv9CjId', 'Rokstarr', 'https://i.scdn.co/image/ab67616d0000b273a9006ae892a2255a865c0f7a', 2009, false, 203866, 75, 46, NULL, 'Taio Cruz', 'SOLO', 'Let''s take a closer look at ''Dynamite'' by Taio Cruz. This upbeat track was written by Cruz himself, along with the talented Max Martin and Dr. Luke. Recorded in London, ''Dynamite'' features a catchy beat that was crafted to get you moving. The song''s lyrics were inspired by Cruz''s desire to create a feel-good anthem, with its infectious chorus designed to lift your spirits. And here''s a fun fact: the song''s music video, directed by Alex Herron, was filmed in Los Angeles and features Cruz dancing through the streets. So, keep it locked right here for more stories that are as explosive as the music!', '2025-07-24 17:33:36.12699');
