INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (87, 'lose yourself', '5Z01UMMf7V1o0MzF86s6WJ', 'Curtain Call: The Hits (Deluxe Edition)', 'https://i.scdn.co/image/ab67616d0000b273eab40fc794b88b9d1e012578', 2002, false, 326466, 80, 58, NULL, 'Eminem', 'SOLO', 'Did you know that ''Lose Yourself'' was written in just three hours? Eminem penned this masterpiece while on the set of the movie ''8 Mile'', inspired by the intensity of the moment. The song''s iconic beat was crafted by producer Jeff Bass, who used a sample from the movie''s score. It became the first rap song to win an Academy Award for Best Original Song. And here''s a fun fact: the original recording had a different third verse, but Eminem re-recorded it to perfection. Keep reaching for those dreams, and keep your radio locked right here!', '2025-07-24 17:33:36.12699');
