INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (92, 'how to save a life', '5fVZC9GiM4e8vu99W0Xf6J', 'How To Save A Life', 'https://i.scdn.co/image/ab67616d0000b27359b8b957f164ce660919f1f4', 2005, false, 262533, 87, 61, NULL, 'The Fray', 'SOLO', 'Let''s uncover the touching story behind ''How to Save a Life''. Did you know that Isaac Slade wrote this song based on his experiences working with troubled teens? The lyrics reflect the struggles and hopes of those trying to make a difference. The song''s emotional intensity was captured in a small studio in Denver, with just a piano and guitar. And here''s a fun fact: the song''s popularity soared after being featured in the TV show ''Grey''s Anatomy'', resonating with millions. It''s a powerful reminder of the impact we can have on each other''s lives. Keep making a difference, and stay tuned for more!', '2025-07-24 17:33:36.12699');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (90, 'viva la vida', '1mea3bSkSGXuIRvnydlB5b', 'Viva La Vida or Death and All His Friends', 'https://i.scdn.co/image/ab67616d0000b273e21cc1db05580b6f2d2a3b6e', 2008, false, 242373, 91, 59, NULL, 'Coldplay', 'GROUP', 'Let''s delve into the magic of ''Viva La Vida'' by Coldplay. This track was a bold departure for the band, embracing a more orchestral sound inspired by historical figures and art. Recorded at the historic Church Studios, the song''s strings were arranged by the talented Davide Rossi, adding a majestic flair. Did you know? The song''s title, translating to ''Long Live Life,'' reflects its uplifting message. And here''s a fun fact: the iconic artwork was inspired by Frida Kahlo''s self-portraits. Keep celebrating life, and stay tuned for more musical journeys!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (93, 'how you remind me', '0gmbgwZ8iqyMPmXefof8Yf', 'Silver Side Up', 'https://i.scdn.co/image/ab67616d0000b273699a422d25adc550dc5aa11c', 2001, false, 223840, 88, 62, NULL, 'Nickelback', 'SOLO', 'Now, let''s dive into the story behind ''How You Remind Me'' by Nickelback. This track was penned by Chad Kroeger in a moment of personal reflection, capturing the essence of a relationship''s ups and downs. Recorded in the iconic Greenhouse Studios in Vancouver, the song''s production was a labor of love, with Kroeger and producer Rick Parashar meticulously crafting each note. Fun fact: the iconic guitar riff was inspired by a melody Chad hummed in the shower! And there you have it, folks, a song that not only topped the charts but also touched hearts worldwide. Keep those dials tuned right here!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (94, 'in the end', '60a0Rd6pjrkxjPbaKzXjfq', 'Hybrid Theory (Bonus Edition)', 'https://i.scdn.co/image/ab67616d0000b273e2f039481babe23658fc719a', 2000, false, 216880, 92, 63, NULL, 'Linkin Park', 'GROUP', 'Let''s take a closer look at ''In the End'' by Linkin Park. This track was a collaborative effort between Mike Shinoda and Chester Bennington, born out of late-night sessions in their makeshift studio. The song''s iconic piano riff was actually played by Shinoda, showcasing his versatility. Did you know that ''In the End'' was one of the last songs recorded for the ''Hybrid Theory'' album? It''s a testament to perseverance and creativity. And remember, folks, no matter where life takes you, keep rocking with us here on the radio!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (95, 'boulevard of broken dreams', '0U87auHx1iZTEFcq9KVdmO', 'American Idiot (20th Anniversary Deluxe Edition)', 'https://i.scdn.co/image/ab67616d0000b2738214d54694cb9813927f7f3f', 2004, false, 260936, 81, 64, NULL, 'Green Day', 'GROUP', 'Now, let''s explore the magic behind ''Boulevard of Broken Dreams'' by Green Day. Billie Joe Armstrong wrote this anthem during a solitary walk in New York City, channeling feelings of isolation and longing. The song was recorded in the legendary Ocean Way Recording studio in Hollywood, where the band experimented with a more stripped-down sound. Trivia time: the iconic guitar riff was inspired by The Beatles'' ''Strawberry Fields Forever.'' So, keep walking down that boulevard with us, and stay tuned for more hits!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (96, 'dani california', '10Nmj3JCNoMeBQ87uw5j8k', 'Stadium Arcadium', 'https://i.scdn.co/image/ab67616d0000b27309fd83d32aee93dceba78517', 2006, false, 282160, 83, 65, NULL, 'Red Hot Chili Peppers', 'GROUP', 'Let''s delve into the story of ''Dani California'' by Red Hot Chili Peppers. This track was a collaborative effort between Anthony Kiedis and John Frusciante, inspired by a fictional character named Dani. The song was recorded at The Mansion in Los Angeles, a historic studio known for its eerie atmosphere. Did you know that the iconic bassline was crafted by Flea in just one take? It''s a testament to the band''s raw talent and energy. So, keep rocking with us, and we''ll see you on the other side!', '2025-07-24 18:40:25.024139');
