INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (82, 'complicated', '5xEM5hIgJ1jjgcEBfpkt2F', 'Let Go', 'https://i.scdn.co/image/ab67616d0000b273f7ec724fbf97a30869d06240', 2002, false, 244506, 86, 54, NULL, 'Avril Lavigne', 'SOLO', 'Let''s explore the magic behind ''Complicated'' by Avril Lavigne. This song was crafted by Avril and her team, reflecting on the complexities of teenage life. Recorded at the famous 2nd Street Studio, the track features some catchy guitar riffs, adding to its youthful energy. Fun fact: the song''s music video, shot in a mall, captures the song''s relatable theme perfectly. And did you know? ''Complicated'' became a defining hit for Avril, launching her into pop-punk stardom. Keep embracing life''s complexities, and stay tuned for more!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (120, 'sk8er boi', '00Mb3DuaIH1kjrwOku9CGU', 'Let Go', 'https://i.scdn.co/image/ab67616d0000b273f7ec724fbf97a30869d06240', 2002, false, 204000, 82, 54, NULL, 'Avril Lavigne', 'SOLO', 'Now, let''s dive into the story behind ''Sk8er Boi''. This track was penned by Avril Lavigne and her guitarist Evan Taubenfeld during a spontaneous jam session in the studio. The song''s catchy riff was inspired by a melody Evan was playing around with, and Avril quickly crafted the lyrics around it. ''Sk8er Boi'' not only topped the charts but also became a cultural phenomenon, sparking debates about class and romance. It was recorded in just a few takes, capturing the raw energy that made it an instant classic. And remember, folks, keep your ears open for those hidden gems in every song!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (121, 'im with you', '1jlG3KJ3gdYmhfuySFfpO1', 'Let Go', 'https://i.scdn.co/image/ab67616d0000b273f7ec724fbf97a30869d06240', 2002, false, 223066, 80, 54, NULL, 'Avril Lavigne', 'SOLO', 'Let''s take a closer look at ''I''m With You''. This heartfelt ballad was written by Avril Lavigne, Scott Spock, and Lauren Christy. The song was inspired by Avril''s feelings of loneliness while on tour, and it was recorded in a small, intimate studio setting to capture that emotional rawness. ''I''m With You'' climbed the charts, resonating with listeners worldwide, and even earned a Grammy nomination. The song''s piano intro was a last-minute addition, adding a touch of melancholy that perfectly complements Avril''s soulful vocals. Keep those tissues handy, because this one''s a tear-jerker!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (122, 'here without you', '3NLrRZoMF0Lx6zTlYqeIo4', 'Away From The Sun', 'https://i.scdn.co/image/ab67616d0000b27383c39b0d32eb4a2064e1e228', 2002, false, 238733, 82, 66, NULL, '3 Doors Down', 'SOLO', 'Now, let''s explore the story behind ''Here Without You''. This poignant track was crafted by 3 Doors Down''s Brad Arnold, who wrote the lyrics in just 15 minutes while missing his family on tour. The song was recorded in a barn studio, giving it a unique, rustic sound. ''Here Without You'' soared to the top of the charts, becoming an anthem for those separated from loved ones. The band''s producer, Rick Parashar, added subtle orchestral elements to enhance the song''s emotional depth. So, next time you''re feeling a bit lonely, let this song be your comforting companion!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (123, 'the pretender', '7x8dCjCr0x6x2lXKujYD34', 'Echoes, Silence, Patience & Grace', 'https://i.scdn.co/image/ab67616d0000b27383e260c313dc1ff1f17909cf', 2007, false, 269373, 81, 77, NULL, 'Foo Fighters', 'GROUP', 'Let''s delve into the creation of ''The Pretender''. This powerhouse track was written by Foo Fighters'' Dave Grohl, who drew inspiration from his frustration with the music industry. The song was recorded in Studio 606, and its intense energy was captured in a single take, showcasing the band''s raw talent. ''The Pretender'' not only topped the charts but also became a rallying cry for authenticity in music. The song''s iconic drum intro was a last-minute addition, adding to its explosive impact. Keep rocking, and never stop being true to yourself!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (124, 'chop suey', '2DlHlPMa4M17kufBvI2lEN', 'Toxicity', 'https://i.scdn.co/image/ab67616d0000b27307bc7d2a745636c356b4d0aa', 2001, false, 210240, 88, 80, NULL, 'System of a Down', 'SOLO', 'Now, let''s uncover the story behind ''Chop Suey!''. This explosive track was penned by System of a Down''s Serj Tankian and Daron Malakian, inspired by Daron''s personal struggles. The song was recorded in a marathon session at Hollywood''s Cello Studios, capturing the band''s intense energy. ''Chop Suey!'' not only became a chart-topping hit but also sparked controversy due to its provocative lyrics. The song''s unique blend of heavy guitars and Middle Eastern influences set it apart. So, keep your ears open for those unexpected musical twists!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (125, 'toxicity', '0snQkGI5qnAmohLE7jTsTn', 'Toxicity', 'https://i.scdn.co/image/ab67616d0000b27307bc7d2a745636c356b4d0aa', 2001, false, 218933, 87, 80, NULL, 'System of a Down', 'SOLO', 'Let''s explore the creation of ''Toxicity''. This hard-hitting track was written by System of a Down''s Serj Tankian and Daron Malakian, inspired by the chaos of Los Angeles. The song was recorded in a frenzy at Hollywood''s Cello Studios, capturing the band''s raw energy. ''Toxicity'' not only topped the charts but also became an anthem for those feeling overwhelmed by societal pressures. The song''s iconic bassline was a last-minute addition, adding to its intense impact. So, next time you''re feeling the pressure, let this song be your release!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (126, 'byob', '0EYOdF5FCkgOJJla8DI2Md', 'Mezmerize', 'https://i.scdn.co/image/ab67616d0000b273c65f8d04502eeddbdd61fa71', 2005, false, 255466, 82, 80, NULL, 'System of a Down', 'SOLO', 'Now, let''s dive into the story behind ''B.Y.O.B.''. This politically charged track was penned by System of a Down''s Daron Malakian and Serj Tankian, inspired by the Iraq War. The song was recorded in a heated session at Hollywood''s Cello Studios, capturing the band''s fiery energy. ''B.Y.O.B.'' not only became a chart-topping hit but also sparked debates about war and politics. The song''s unique blend of heavy guitars and jazz influences set it apart. So, keep your ears open for those unexpected musical twists!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (127, 'lonely day', '1VNWaY3uNfoeWqb5U8x2QX', 'Hypnotize', 'https://i.scdn.co/image/ab67616d0000b273f5e7b2e5adaa87430a3eccff', 2005, false, 167906, 84, 80, NULL, 'System of a Down', 'SOLO', 'Let''s take a closer look at ''Lonely Day''. This melancholic track was written by System of a Down''s Serj Tankian and Daron Malakian, inspired by feelings of isolation. The song was recorded in a serene session at Hollywood''s Cello Studios, capturing the band''s emotional depth. ''Lonely Day'' not only resonated with listeners worldwide but also became a soothing balm for those feeling alone. The song''s haunting piano intro was a last-minute addition, adding to its emotional impact. So, next time you''re feeling a bit lonely, let this song be your comforting companion!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (128, 'take me out', '20I8RduZC2PWMWTDCZuuAN', 'Franz Ferdinand', 'https://i.scdn.co/image/ab67616d0000b27309a90531b85be7899c3234c4', 2004, false, 237026, 87, 81, NULL, 'Franz Ferdinand', 'SOLO', 'Now, let''s explore the story behind ''Take Me Out''. This infectious track was penned by Franz Ferdinand''s Alex Kapranos and Nick McCarthy, inspired by a game of pool. The song was recorded in a lively session at Glasgow''s Rockfield Studios, capturing the band''s energetic vibe. ''Take Me Out'' not only topped the charts but also became a dance floor favorite. The song''s iconic guitar riff was a last-minute addition, adding to its irresistible charm. So, next time you''re out, let this song take you away!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (129, 'maps', '0hDQV9X1Da5JrwhK8gu86p', 'Fever To Tell (Deluxe Remastered)', 'https://i.scdn.co/image/ab67616d0000b2731b1cb4ef0f096f9d66fc3dc6', 2003, false, 219986, 73, 82, NULL, 'Yeah Yeah Yeahs', 'SOLO', 'Let''s delve into the creation of ''Maps''. This emotional track was written by Yeah Yeah Yeahs'' Karen O, inspired by a breakup. The song was recorded in a heartfelt session at New York''s Stratosphere Sound, capturing the band''s raw emotion. ''Maps'' not only became a chart-topping hit but also resonated deeply with listeners. The song''s iconic chorus was a last-minute addition, adding to its emotional impact. So, next time you''re feeling a bit lost, let this song guide you back!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (130, 'float on', '2lwwrWVKdf3LR9lbbhnr6R', 'Good News For People Who Love Bad News', 'https://i.scdn.co/image/ab67616d0000b273cc68329bfbf34037df965dc1', 2004, false, 208466, 79, 83, NULL, 'Modest Mouse', 'SOLO', 'Now, let''s dive into the story behind ''Float On'' by Modest Mouse. Did you know that this track was a turning point for the band? It was written by Isaac Brock in a moment of personal struggle, aiming to create something uplifting. Recorded in a small studio in Portland, the song''s infectious beat was inspired by a broken drum machine that gave it that unique groove. ''Float On'' not only climbed the charts but also became an anthem for perseverance. And remember, folks, no matter how tough things get, just keep floating on! Keep it locked right here for more musical magic.', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (131, 'harder to breathe', '4V9JDRqKjN8F2HWdlEDxvI', 'Songs About Jane: 10th Anniversary Edition', 'https://i.scdn.co/image/ab67616d0000b27392f2d790c6a97b195f66d51e', 2002, false, 173693, 69, 84, NULL, 'Maroon 5', 'GROUP', 'Alright, let''s talk about ''Harder to Breathe'' by Maroon 5. This track was born out of frustration, penned by Adam Levine during a time when he felt creatively stifled. The song''s raw energy was captured in a marathon recording session at Larrabee Studios in LA, where the band pushed their limits. Fun fact: the iconic guitar riff was an accidental discovery during a jam session. ''Harder to Breathe'' not only marked Maroon 5''s breakthrough but also resonated with anyone feeling the pressure of life. So, keep breathing, and stay tuned for more hits on this station!', '2025-07-24 18:40:25.024139');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (132, 'ill be there for you', '15tHagkk8z306XkyOHqiip', 'L.P.', 'https://i.scdn.co/image/ab67616d0000b273a2535194dfef3e77437036b5', 1995, false, 188359, 71, 85, NULL, 'The Rembrandts', 'SOLO', 'You might be surprised to learn that ''I''ll Be There for You'' was originally intended to be a one-off for the Friends pilot. But its popularity soared so high that The Rembrandts were asked to include it on their album. The song''s catchy hook was born out of a late-night jam session at Rumbo Recorders, where the band played around with different rhythms until they struck gold. And get this: the iconic opening line was inspired by a random phrase one of the songwriters overheard at a coffee shop. So, keep your dial right here, and we''ll keep the hits coming, just for you!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (133, 'where everybody knows your name', '2uE8l7sar0JT0tZYhrPz8S', 'Keeper', 'https://i.scdn.co/image/ab67616d0000b2736bb85ed5053d24308e49d961', 1983, false, 151266, 49, 86, NULL, 'Gary Portnoy', 'SOLO', 'Let me tell you a little secret about ''Where Everybody Knows Your Name'': it was almost called ''People Like Us''! Gary Portnoy and Judy Hart Angelo crafted this heartwarming tune in a cozy New York studio, aiming to capture the essence of Cheers'' welcoming atmosphere. The song''s warm, inviting feel was achieved with a blend of acoustic guitars and soft percussion, creating that perfect ''home away from home'' vibe. And here''s a fun tidbit: the song''s title phrase was inspired by a line from a poem Gary read. So, stay tuned, and we''ll keep the good times rolling, right here on your favorite station!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (134, 'the fresh prince of belair', '0UREO3QWbXJW3gOUXpK1am', 'Greatest Hits', 'https://i.scdn.co/image/ab67616d0000b2735f9c08c7c4d2f37d5d73ce44', 1988, false, 177266, 60, 87, NULL, 'DJ Jazzy Jeff & The Fresh Prince', 'SOLO', 'Get ready for a fun fact about ''The Fresh Prince of Bel-Air'' theme song: it was recorded in just one take! DJ Jazzy Jeff and Will Smith, aka The Fresh Prince, brought their signature style to the track, blending hip-hop beats with a catchy narrative. The song was crafted at Sigma Sound Studios in Philadelphia, where the duo experimented with different sound effects to capture the essence of Will''s journey. And did you know that the iconic ''yo, homes'' line was improvised on the spot? So, keep your radio locked right here, and we''ll keep the party going with more great tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (135, 'the golden girls', '2i9ufVEMOr9jb0AbTGequu', 'Movie Soundtrack - Songs from Film & Tv', 'https://i.scdn.co/image/ab67616d0000b27396e893c7f9216dd50e28099e', 1996, false, 282706, 3, 88, NULL, 'Andrew Gold', 'SOLO', 'Here''s a little-known fact about ''The Golden Girls'' theme song: Andrew Gold wrote it in just one afternoon! Inspired by the show''s theme of friendship and laughter, Gold crafted this uplifting tune at his home studio in Los Angeles. The song''s cheerful melody was achieved with a mix of acoustic and electric guitars, giving it that warm, inviting feel. And get this: the iconic ''thank you for being a friend'' line was inspired by a greeting card Gold received. So, keep your dial right here, and we''ll keep the good times rolling with more fantastic tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (136, 'the jeffersons', '7u2g43fY31gjpPoLM7NJTG', 'Movin'' On Up (From "The Jeffersons") [Piano Version]', 'https://i.scdn.co/image/ab67616d0000b27328f54565b0b80282d69b5234', 1975, false, 132486, 4, 89, NULL, 'Ja''Net DuBois', 'SOLO', 'Did you know that ''The Jeffersons'' theme song, ''Movin'' On Up,'' was written by Ja''Net DuBois herself? She penned this uplifting anthem in her living room, inspired by the show''s theme of upward mobility. The song''s catchy melody was recorded at a small studio in Los Angeles, where DuBois experimented with different vocal styles to capture the song''s joyful spirit. And here''s a fun fact: the iconic ''fish don''t fry in the kitchen'' line was inspired by a childhood memory of DuBois''. So, keep your radio tuned right here, and we''ll keep the good times rolling with more fantastic tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (137, 'the brady bunch', '1HyLRvrwqChIybFqycgu3M', 'It''s A Sunshine Day : The Best Of The Brady Bunch', 'https://i.scdn.co/image/ab67616d0000b2734cc5ae1a7de063cb700b725d', 1970, false, 58933, 39, 91, NULL, 'The Brady Bunch', 'SOLO', 'Here''s a fun fact about ''The Brady Bunch'' theme song: it was recorded by the actual cast members! The song''s cheerful melody was crafted by Sherwood Schwartz and Frank De Vol at a studio in Hollywood, where the kids'' voices were layered to create that iconic sound. And did you know that the song''s title, ''The Brady Bunch,'' was almost ''The Brady Brood''? So, keep your dial right here, and we''ll keep the good times rolling with more fantastic tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (138, 'the munsters', '5GAG0ZZmZeMQWMAvNGfoLT', 'The Munsters (Original Motion Picture Soundtrack)', 'https://i.scdn.co/image/ab67616d0000b27328eb6fe38bb8dfa087b66a1e', 1964, false, 33186, 16, 92, NULL, 'Jack Marshall', 'SOLO', 'Let me share a little-known fact about ''The Munsters'' theme song: it was composed by Jack Marshall in just one day! Inspired by the show''s quirky characters, Marshall crafted this catchy tune at a studio in Los Angeles, blending surf rock elements with a spooky twist. The song''s iconic opening riff was achieved with a unique guitar sound, giving it that eerie yet fun vibe. And here''s a fun tidbit: the song''s title was inspired by a line from a horror movie Marshall watched. So, keep your radio locked right here, and we''ll keep the party going with more great tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (139, 'the beverly hillbillies', '29qFlNOssruDfoEN8vN2Uu', 'Town and Country', 'https://i.scdn.co/image/ab67616d0000b273eb29e3e4514ef5f374778827', 1962, false, 140413, 52, 93, NULL, 'Flatt & Scruggs', 'SOLO', 'Here''s a little-known fact about ''The Beverly Hillbillies'' theme song: it was written by Paul Henning, the show''s creator, in just one evening! Flatt and Scruggs brought their bluegrass magic to the track, recording it at RCA Studio B in Nashville. The song''s catchy banjo riff was inspired by a traditional folk tune, giving it that down-home feel. And did you know that the iconic ''come and listen to my story'' line was inspired by a phrase Henning''s grandfather used to say? So, keep your dial right here, and we''ll keep the good times rolling with more fantastic tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (140, 'the andy griffith show', 'b6ad05c1f23a4373', 'Themes And Laughs From The Andy Griffith Show', 'https://i.scdn.co/image/ab67616d0000b273026813251389030d56973acd', 1958, false, 146666, 9, 94, NULL, 'Earle Hagen', 'SOLO', 'Did you know that ''The Andy Griffith Show'' theme song was composed by Earle Hagen in just one afternoon? Inspired by the show''s small-town charm, Hagen crafted this iconic tune at a studio in Hollywood, blending a simple whistled melody with a warm, folksy feel. The song''s catchy whistle was performed by Hagen himself, giving it that personal touch. And here''s a fun fact: the song''s title was inspired by a line from a poem Hagen read. So, keep your radio tuned right here, and we''ll keep the good times rolling with more fantastic tunes!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (141, 'the twilight zone', '1i2ZoD6uWR4BjIhNuVhmW4', 'Pops Out Of This World', 'https://i.scdn.co/image/ab67616d0000b273e2945b30cec835cf9b8aa357', 1960, false, 218066, 17, 95, NULL, 'Marius Constant', 'SOLO', 'Now, let''s dive into the fascinating world of ''The Twilight Zone'' theme. Composed by Marius Constant, this iconic piece was actually created from two separate pieces of music, ''Milieu No. 2'' and ''Étrange No. 3'', which were later combined to form the eerie and unforgettable theme we all know. Recorded at the CBS Television City in Hollywood, the use of unconventional instruments like the Ondioline adds a unique flavor to the sound. And here''s a fun fact for you: the theme was so popular that it was even used in a 1960s dance craze called ''The Twilight Zone Dance''! Keep your dial right here, folks, as we keep exploring the magic of music.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (142, 'hawaii fiveo', '3UUwbJd2j4RORlalTUhaDk', 'Hawaii Five-O', 'https://i.scdn.co/image/ab67616d0000b2737c143568dc90032dea8d6183', 1969, false, 113893, 53, 97, NULL, 'The Ventures', 'SOLO', 'Let''s take a stroll through the surf rock paradise of ''Hawaii Five-O'' by The Ventures. This track, penned by Morton Stevens, not only became a chart-topping hit but also inspired countless surf rock bands to pick up their guitars. Recorded at the legendary Western Recorders studio in Hollywood, the song''s distinctive sound comes from the use of a Fender Jazzmaster guitar. Did you know that the song was so popular that it was even used as the theme for the 1980s video game ''Hawaii''? Stick around, music lovers, as we continue our journey through the waves of sound.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (143, 'mission impossible', '2QqouLGFYMynquwDMYUGk1', 'More Mission: Impossible', 'https://i.scdn.co/image/ab67616d0000b27339b4c54673ada0808ca87afe', 1967, false, 117733, 43, 98, NULL, 'Lalo Schifrin', 'SOLO', 'Let''s embark on a thrilling mission with ''Mission: Impossible'' by Lalo Schifrin. This iconic theme was crafted in the heart of Hollywood at the Goldwyn Sound Stage, where Schifrin''s innovative use of a piccolo trumpet gave the track its signature edge. The song''s impact was so profound that it inspired a whole genre of spy music. And here''s a bit of trivia for you: the theme was originally written in a 5/4 time signature, but was later changed to 6/8 for the TV series. Keep your ears tuned right here, folks, as we continue our musical adventure.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (144, 'peter gunn', '3RRdmSE4Vytb60hakTWNb3', 'Music From Peter Gunn', 'https://i.scdn.co/image/ab67616d0000b27345ea9c58a203d18bdaf906c6', 1959, false, 126333, 43, 99, NULL, 'Henry Mancini', 'SOLO', 'Let''s swing into the cool world of ''Peter Gunn'' by Henry Mancini. This jazz-infused theme was recorded at the RCA Victor Studio in Hollywood, where Mancini''s use of a muted trumpet and a walking bass line set the tone for the entire genre of detective show music. The song''s success led to a Grammy win for Best Arrangement in 1959. And did you know that the theme was so popular that it inspired a short-lived dance called ''The Peter Gunn''? Keep your dial right here, music fans, as we keep grooving through the hits.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (145, 'dragnet', '7C13pyEILCVb39qvh0xtPA', 'Best Film-Noir Music of the 1950s, Vol.1 (Remastered 2024)', 'https://i.scdn.co/image/ab67616d0000b27372820f76739493cde89bf08b', 1953, false, 168124, 1, 100, NULL, 'Walter Schumann', 'SOLO', 'Let''s step into the noir world of ''Dragnet'' by Walter Schumann. This iconic theme was recorded at the MGM Scoring Stage in Culver City, where Schumann''s use of a four-note motif became synonymous with police procedurals. The song''s impact was so significant that it was even parodied in numerous TV shows and movies. And here''s a fun fact: the theme was originally written for a radio show before making its way to television. Stay tuned, folks, as we continue our journey through the sounds of the past.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (146, 'the pink panther theme', '0juPSJLFnLFim7BK6VzTes', 'The Pink Panther - Original Soundtrack', 'https://i.scdn.co/image/ab67616d0000b273e97407bb9fdb339614c3c7c1', 1963, false, 157680, 56, 99, NULL, 'Henry Mancini', 'SOLO', 'Let''s slip into the suave world of ''The Pink Panther Theme'' by Henry Mancini. This playful piece was recorded at the RCA Victor Studio in Hollywood, where Mancini''s use of a tenor saxophone and a whimsical melody set the tone for the entire franchise. The song''s success led to a Grammy win for Best Instrumental Arrangement in 1964. And did you know that the theme was so popular that it inspired a dance called ''The Pink Panther''? Keep your ears tuned right here, music lovers, as we continue our musical escapade.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (147, 'batman theme', '3mICEHCCKuOrd6a3c8atst', 'The Music Of DC Comics: Vol. 2', 'https://i.scdn.co/image/ab67616d0000b2732c2213da3d68c7192bd21c28', 1966, false, 46893, 31, 103, NULL, 'Neal Hefti', 'SOLO', 'Let''s soar into the superhero world of the ''Batman Theme'' by Neal Hefti. This iconic piece was recorded at the Goldwyn Sound Stage in Hollywood, where Hefti''s use of a driving bass line and a catchy melody became synonymous with the Caped Crusader. The song''s impact was so profound that it inspired countless covers and parodies. And here''s a fun fact: the theme was originally written in a 12/8 time signature, but was later simplified for the TV series. Stay tuned, folks, as we continue our journey through the sounds of heroism.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (148, 'star trek', '1LaQ3RGV5wfIGEAsdUlkWA', 'The Ultimate Star Trek', 'https://i.scdn.co/image/ab67616d0000b273a7c00749fc2ff50e1cc184f4', 1966, false, 84093, 32, 104, NULL, 'Alexander Courage', 'SOLO', 'Let''s embark on a cosmic journey with the ''Star Trek'' theme by Alexander Courage. This iconic piece was recorded at the Desilu Studios in Hollywood, where Courage''s use of a theremin and a soaring melody set the tone for the entire franchise. The song''s impact was so significant that it inspired countless sci-fi themes. And did you know that the theme was originally written for a different show before being adapted for ''Star Trek''? Keep your dial right here, music fans, as we continue our voyage through the stars.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (149, 'the simpsons', '1ipM6x72sFUJvNkmZxedl2', 'The City of Prague Philharmonic Orchestra Plays The Music Of Danny Elfman', 'https://i.scdn.co/image/ab67616d0000b273c8a3eecf982367241d99af30', 1997, false, 101813, 19, 106, NULL, 'Danny Elfman', 'SOLO', 'Let''s dive into the animated world of ''The Simpsons'' theme by Danny Elfman. This catchy piece was recorded at the Todd-AO Scoring Stage in Hollywood, where Elfman''s use of a quirky melody and a playful arrangement set the tone for the entire series. The song''s impact was so profound that it inspired countless covers and parodies. And here''s a fun fact: the theme was originally written for a different show before being adapted for ''The Simpsons''. Stay tuned, folks, as we continue our journey through the sounds of Springfield.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (150, 'xfiles', '2v4pLHpKG2c3HuY0Sv8xrq', 'X Files - I Want To Believe / OST', 'https://i.scdn.co/image/ab67616d0000b27337b70585050a1552fccfa60b', 1996, false, 351146, 26, 108, NULL, 'Mark Snow', 'SOLO', 'Let''s delve into the mysterious world of the ''X-Files'' theme by Mark Snow. This eerie piece was recorded at the Paramount Scoring Stage in Hollywood, where Snow''s use of a synthesizer and a haunting melody set the tone for the entire series. The song''s impact was so significant that it inspired countless sci-fi themes. And did you know that the theme was originally written for a different show before being adapted for ''The X-Files''? Keep your ears tuned right here, music lovers, as we continue our journey through the unknown.', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (151, 'law and order', '0IpOLDDlfk0I902oJMIBdK', 'Inventions From The Blue Line', 'https://i.scdn.co/image/ab67616d0000b27345f45174d7386556867f01b9', 1990, false, 195800, 32, 109, NULL, 'Mike Post', 'SOLO', 'Mike Post''s ''Law and Order'' theme is a masterclass in tension and urgency, crafted to keep viewers glued to their seats. Did you know that Post wrote this iconic piece in just a few hours, inspired by the gritty realism of the show? The use of a driving bass line and sharp percussive elements was a deliberate choice to mirror the relentless pursuit of justice. And here''s a fun fact: the theme was so effective that it was used in multiple international versions of the show, proving its universal appeal. Keep your dial right here for more fascinating stories behind the music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (152, 'csi crime scene investigation', '0cJPLFrlV7TTCyPLupHzcH', 'Who''s Next (Deluxe Edition)', 'https://i.scdn.co/image/ab67616d0000b273fe24dcd263c08c6dd84b6e8c', 1978, false, 511400, 68, 110, NULL, 'The Who', 'GROUP', 'The Who''s ''CSI: Crime Scene Investigation'' theme, ''Who Are You,'' was originally released in 1978 but found a new life in the early 2000s. Did you know that the song''s inclusion in the series was a last-minute decision, chosen for its questioning lyrics that perfectly matched the show''s investigative nature? The track was recorded at London''s Ramport Studios, where the band''s raw energy was captured in a way that still resonates with audiences today. And here''s a bit of trivia: the song''s iconic piano intro was played by none other than Roger Daltrey himself. Stay tuned for more behind-the-scenes magic!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (153, 'the sopranos', '0DHsVUhrKPAX3kpbyeb7B0', 'The Wimmin from W.O.M.B.L.E, Vol. 2', 'https://i.scdn.co/image/ab67616d0000b273d065270205feb58aeb88ed80', 1997, false, 197552, 37, 111, NULL, 'Alabama 3', 'SOLO', 'Alabama 3''s ''The Sopranos'' theme, ''Woke Up This Morning,'' is a soulful blend of blues and electronica that perfectly captures the show''s dark and gritty atmosphere. Did you know that the song was originally inspired by a real-life incident involving a friend of the band''s lead singer? The track was recorded in a small studio in London, where the band''s unique sound was born from a mix of live instruments and electronic beats. And here''s a fun fact: the song''s opening line was sampled from a 1960s gospel record, adding an extra layer of depth to its haunting melody. Keep it locked right here for more intriguing tales from the world of music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (154, 'the west wing', '09w6MNV0x0u4HmSnu2hJOy', 'The West Wing (Original Television Soundtrack)', 'https://i.scdn.co/image/ab67616d0000b2739ed595fe03a14d749ed56658', 2000, false, 232933, 19, 112, NULL, 'W.G. Snuffy Walden', 'SOLO', 'W.G. Snuffy Walden''s ''The West Wing'' theme is a stirring piece that encapsulates the show''s blend of drama and idealism. Did you know that Walden composed this piece in his home studio, drawing inspiration from the show''s focus on political integrity? The theme''s use of strings and piano creates a sense of urgency and hope, reflecting the show''s narrative. And here''s a bit of trivia: Walden was so dedicated to capturing the right mood that he reworked the theme multiple times until it perfectly matched the show''s vision. Stay with us for more captivating stories behind the music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (155, 'er', '0FCccVZfdb2JxqtO9UXrYm', 'Fantastic Beasts and Where to Find Them (Original Motion Picture Soundtrack)', 'https://i.scdn.co/image/ab67616d0000b273d12ff73aa7184b65484edf27', 1997, false, 208762, 28, 113, NULL, 'James Newton Howard', 'SOLO', 'James Newton Howard''s ''ER'' theme is a heart-pounding piece that perfectly captures the show''s high-stakes medical drama. Did you know that Howard composed this theme in his Los Angeles studio, using a combination of orchestral and electronic elements to create a sense of urgency? The theme''s use of a driving rhythm and soaring strings was a deliberate choice to reflect the show''s life-and-death scenarios. And here''s a fun fact: Howard was so committed to the project that he spent weeks perfecting the theme to ensure it captured the show''s emotional intensity. Keep your radio tuned right here for more behind-the-scenes insights!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (156, 'the oc', '497Fkp3gRiGrRMoqBTDudr', 'The Guest (Expanded Edition)', 'https://i.scdn.co/image/ab67616d0000b2733fffc3b7f3db4dcccff523e1', 2002, false, 193933, 66, 114, NULL, 'Phantom Planet', 'SOLO', 'Phantom Planet''s ''The O.C.'' theme, ''California,'' is an infectious anthem that perfectly captures the show''s sunny, youthful vibe. Did you know that the song was written by the band''s lead singer, Alex Greenwald, in just a few hours, inspired by the show''s setting in Orange County? The track was recorded in a small studio in Los Angeles, where the band''s energetic sound was captured in a way that still resonates with audiences today. And here''s a bit of trivia: the song''s catchy chorus was originally a placeholder, but it ended up becoming the song''s defining feature. Stay tuned for more fascinating stories behind the music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (157, 'scrubs', '3ffJKEoVfbiSlDHztViu6O', 'Scrubs', 'https://i.scdn.co/image/ab67616d0000b27386741ccef95520764f72e866', 2002, false, 218813, 32, 115, NULL, 'Lazlo Bane', 'SOLO', 'Lazlo Bane''s ''Scrubs'' theme, ''Superman,'' is a quirky and uplifting song that perfectly matches the show''s blend of humor and heart. Did you know that the song was written by the band''s lead singer, Chad Fischer, as a tribute to his father, who was a doctor? The track was recorded in a small studio in Los Angeles, where the band''s unique sound was born from a mix of live instruments and electronic beats. And here''s a fun fact: the song''s opening line was inspired by a conversation Fischer had with his father about the challenges of being a doctor. Keep it locked right here for more intriguing tales from the world of music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (158, 'the office', '0xpCrenke52qC3nY4f2ckT', 'The Office (Dashiin Remix)', 'https://i.scdn.co/image/ab67616d0000b2731f377fca5b39a58ee3728e9b', 2005, false, 254869, 11, 116, NULL, 'The Scrantones', 'SOLO', 'The Scrantones'' ''The Office'' theme is a quirky and catchy piece that perfectly captures the show''s blend of humor and awkwardness. Did you know that the theme was composed by the show''s creator, Greg Daniels, who wanted a sound that reflected the show''s unique setting in Scranton, Pennsylvania? The track was recorded in a small studio in Los Angeles, where the band''s playful energy was captured in a way that still resonates with audiences today. And here''s a bit of trivia: the theme''s use of a xylophone was a deliberate choice to add a touch of whimsy to the show''s opening. Stay with us for more captivating stories behind the music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (159, 'lost', '0DNhUQCTDdAtuvxZXQ6krk', 'Lost: The Final Season (Original Television Soundtrack)', 'https://i.scdn.co/image/ab67616d0000b273864237f5bcb3f64e70199b00', 2005, false, 474506, 40, 118, NULL, 'Michael Giacchino', 'SOLO', 'Michael Giacchino''s ''Lost'' theme is a haunting and mysterious piece that perfectly captures the show''s sense of adventure and intrigue. Did you know that Giacchino composed this theme in his home studio, drawing inspiration from the show''s focus on survival and mystery? The theme''s use of a driving rhythm and eerie strings creates a sense of urgency and suspense, reflecting the show''s narrative. And here''s a fun fact: Giacchino was so dedicated to capturing the right mood that he reworked the theme multiple times until it perfectly matched the show''s vision. Keep your radio tuned right here for more behind-the-scenes insights!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (160, 'house', '5o4lKT0ReFi73HuFexWEIY', 'Лучшие хиты: Trip Hop', 'https://i.scdn.co/image/ab67616d0000b273e622f6a4de8ac55ddf2ef889', 1998, false, 324933, 45, 119, NULL, 'Massive Attack', 'SOLO', 'Massive Attack''s ''House'' theme, ''Teardrop,'' is a haunting and atmospheric piece that perfectly captures the show''s blend of medical drama and mystery. Did you know that the song was originally released in 1998 but found a new life in the early 2000s as the theme for ''House''? The track was recorded in a small studio in Bristol, where the band''s unique sound was born from a mix of live instruments and electronic beats. And here''s a bit of trivia: the song''s use of a sampled heartbeat was a deliberate choice to reflect the show''s focus on medical diagnostics. Stay tuned for more fascinating stories behind the music!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (161, 'desperate housewives', '2iuPMHqU7dvKK4ezEBTAgh', 'Desperate Housewives (TV Soundtrack)', 'https://i.scdn.co/image/ab67616d0000b27378804dd9c109691dbd318164', 2004, false, 40453, 29, 106, NULL, 'Danny Elfman', 'SOLO', 'Now, let''s dive into the magic behind ''Desperate Housewives''. Danny Elfman crafted this theme with a blend of suspense and whimsy, perfectly capturing the essence of the show. Recorded in his favorite studio, the piece features an eerie yet captivating violin solo that sets the tone for the series. Did you know that Elfman initially hesitated to take on the project, but once he did, he poured his heart into every note? And that''s a wrap on this haunting melody, folks!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (162, '24', '7drVZwMjU1tzXX0v1ldifT', '24: The Game', 'https://i.scdn.co/image/ab67616d0000b273eea549d82dc8935fad7f092a', 2002, false, 288293, 13, 121, NULL, 'Sean Callery', 'SOLO', 'Sean Callery''s ''24'' theme is a masterclass in tension-building. The track was recorded in a marathon session, with Callery pushing the boundaries of traditional scoring. The use of a ticking clock in the background was a stroke of genius, symbolizing the real-time nature of the show. Fun fact: Callery once said that the theme was inspired by his own experiences with time management. And there you have it, a theme that keeps you on the edge of your seat!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (163, 'the wire', '4RjvJrkTa7gYOvk5tm94YW', '...and all the pieces matter, Five Years of Music from The Wire (deluxe version)', 'https://i.scdn.co/image/ab67616d0000b273f0d0ac07e9d9a6f8f15fd53c', 1982, false, 104480, 31, 122, NULL, 'Tom Waits', 'SOLO', 'Tom Waits brought his unique style to ''The Wire'' theme, infusing it with a gritty, urban feel. The song was recorded in a makeshift studio in Baltimore, adding an authentic touch to the sound. Waits'' raspy vocals and the haunting piano melody perfectly encapsulate the show''s atmosphere. Did you know that Waits was a fan of the series before he agreed to contribute? And that''s the story behind this unforgettable theme!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (164, 'breaking bad', '2hsLpiKNkWpd4e9QuVdhar', 'Breaking Bad: Original Score from the Television Series', 'https://i.scdn.co/image/ab67616d0000b2732aabcf79e0240e36f95877b5', 2009, false, 75666, 51, 123, NULL, 'Dave Porter', 'SOLO', 'Dave Porter''s ''Breaking Bad'' theme is a journey through the dark and intense world of the series. The track was meticulously crafted to reflect the show''s escalating tension, with Porter using unconventional instruments like the cello and the theremin. Recorded in a small studio in Albuquerque, the theme captures the essence of the show''s setting. Trivia time: Porter once mentioned that the theme evolved as the series did, mirroring Walter White''s transformation. And that''s the tale of this gripping score!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (165, 'mad men', '1k5f1jOidJH55R0yLeZB0X', 'A Beautiful Mine (Mad Men Instrumental Theme) [From "Retrospective: The Music Of Mad M]', 'https://i.scdn.co/image/ab67616d0000b27393027a8b1dd5bd8ab58a4203', 2002, false, 205573, 13, 124, NULL, 'RJD2', 'SOLO', 'RJD2''s ''Mad Men'' theme, ''A Beautiful Mine'', is a blend of vintage and modern sounds that perfectly complements the show''s aesthetic. The track was recorded in a studio filled with old-school equipment, giving it that authentic 60s vibe. RJD2''s use of vinyl crackles and jazz elements adds a layer of sophistication. Fun fact: the theme was initially rejected but later embraced as the perfect fit. And that''s the story behind this stylish tune!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (166, 'true blood', '4ytPgUsPNsKJtmM6Vjr4oS', 'TRUE BLOOD (Music from the HBO® Original Series)', 'https://i.scdn.co/image/ab67616d0000b2732a1072b4272e0b3115400d45', 2006, false, 163093, 35, 125, NULL, 'Jace Everett', 'SOLO', 'Jace Everett''s ''True Blood'' theme, ''Bad Things'', is a sultry and seductive piece that sets the mood for the series. The song was recorded in a Nashville studio, with Everett''s deep, resonant voice adding to the allure. The use of a slide guitar gives it a haunting quality that fits the show''s supernatural theme. Did you know that Everett was inspired by classic blues when writing this track? And that''s the scoop on this mesmerizing theme!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (167, 'dexter', '32A1xdQk9lRSFn5CEY5M2S', 'Dexter Season 4', 'https://i.scdn.co/image/ab67616d0000b273d43946089226e9e1aac70a83', 2007, false, 102973, 39, 126, NULL, 'Rolfe Kent', 'SOLO', 'Rolfe Kent''s ''Dexter'' theme is a chilling and intricate piece that mirrors the show''s dark narrative. The track was recorded in a studio in Los Angeles, with Kent using a mix of orchestral and electronic elements to create a sense of unease. The theme''s use of a solo cello adds a personal touch to the score. Trivia time: Kent once said that the theme was designed to reflect Dexter''s dual nature. And that''s the story behind this eerie melody!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (168, 'weeds', '3qnWCB2E4wbuz6OYLpClyD', 'Weeds (Music from the Original Series)', 'https://i.scdn.co/image/ab67616d0000b273e12bf606313af261012005dd', 1967, false, 100293, 17, 127, NULL, 'Malvina Reynolds', 'SOLO', 'Malvina Reynolds'' ''Weeds'' theme, ''Little Boxes'', is a quirky and catchy tune that perfectly captures the show''s satirical tone. The song was recorded in a small studio in Berkeley, with Reynolds'' distinctive voice and simple guitar accompaniment. The theme''s use of repetitive lyrics adds to its charm. Fun fact: Reynolds wrote the song as a critique of suburban conformity, which aligns well with the series'' themes. And that''s the tale of this delightful track!', '2025-07-25 10:56:04.571883');
INSERT INTO track_tables.track (id, track_name, spotify_track_id, album_name, album_artwork, year_released, is_explicit, duration_ms, popularity, artist_id, featured_artist_id, artist_display_name, mode_flag, detail, created_at) VALUES (169, 'entourage', '3LkejeQBFNMImUYEG0cXWV', 'The Royal Tenenbaums (Original Soundtrack)', 'https://i.scdn.co/image/ab67616d0000b273d6f0f7fa3ad98aa1d40a5c2b', 2004, false, 272133, 25, 128, NULL, 'Mark Mothersbaugh', 'SOLO', 'Mark Mothersbaugh''s ''Entourage'' theme is a vibrant and energetic piece that reflects the show''s fast-paced lifestyle. The track was recorded in a studio in Los Angeles, with Mothersbaugh using a mix of electronic and orchestral elements to create a dynamic sound. The theme''s use of a driving beat adds to the excitement. Did you know that Mothersbaugh was inspired by the show''s characters when composing this track? And that''s the story behind this lively theme!', '2025-07-25 10:56:04.571883');
